      facts: [{"sourceId": "K008", "factId": "F001", "content": "while 会在条件为 True 时重复执行代码块。", "source_id": "K008", "fact_id": "F001"}, {"sourceId": "K008", "factId": "F002", "content": "对需要结束的 while 循环，应保证存在退出路径以避免意外的无限循环：可以更新影响条件的状态使条件变为 False，也可以用 break 退出。", "source_id": "K008", "fact_id": "F002"}, {"sourceId": "K008", "factId": "F003", "content": "while 适合重复次数不确定但停止条件明确的任务。", "source_id": "K008", "fact_id": "F003"}, {"sourceId": "K008", "factId": "F004", "content": "while 每次迭代前先判断条件，条件为 False 时退出循环。", "source_id": "K008", "fact_id": "F004"}, {"sourceId": "K008", "factId": "F005", "content": "break 可立即终止整个循环。", "source_id": "K008", "fact_id": "F005"}, {"sourceId": "K008", "factId": "F006", "content": "continue 跳过本次迭代，直接回到条件判断。", "source_id": "K008", "fact_id": "F006"}, {"sourceId": "K008", "factId": "F007", "content": "while 可搭配 else，条件变 False 正常结束时执行 else。", "source_id": "K008", "fact_id": "F007"}, {"sourceId": "K008", "factId": "F008", "content": "while True 配合 break 可实现先执行后判断的循环结构。", "source_id": "K008", "fact_id": "F008"}, {"sourceId": "K008", "factId": "F009", "content": "死循环会持续占用 CPU，导致程序卡死或无响应。", "source_id": "K008", "fact_id": "F009"}, {"sourceId": "K008", "factId": "F010", "content": "循环变量应在循环外初始化，在循环内更新。", "source_id": "K008", "fact_id": "F010"}, {"sourceId": "K008", "factId": "F011", "content": "while 适合轮询状态或等待满足条件再退出的场景。", "source_id": "K008", "fact_id": "F011"}, {"sourceId": "K008", "factId": "F012", "content": "循环体内至少要有一条语句，暂无逻辑时用 pass 占位。", "source_id": "K008", "fact_id": "F012"}],
