      facts: [{"sourceId": "K012", "factId": "F001", "content": "字符串是字符序列。", "source_id": "K012", "fact_id": "F001"}, {"sourceId": "K012", "factId": "F002", "content": "s.split(sep) 按分隔符 sep 拆分字符串 s，并返回由各段组成的列表。", "source_id": "K012", "fact_id": "F002"}, {"sourceId": "K012", "factId": "F003", "content": "sep.join(parts) 用分隔符 sep 连接字符串序列 parts，并返回连接后的新字符串。", "source_id": "K012", "fact_id": "F003"}, {"sourceId": "K012", "factId": "F004", "content": "字符串不可原地修改字符；文本变换可以返回字符串，拆分和查询等操作的返回类型由具体方法决定。", "source_id": "K012", "fact_id": "F004"}, {"sourceId": "K012", "factId": "F005", "content": "字符串支持索引与切片，如 s[0]、s[1:3]。", "source_id": "K012", "fact_id": "F005"}, {"sourceId": "K012", "factId": "F006", "content": "len(s) 返回字符串 s 的字符数量，中文字符按一个字符计数。", "source_id": "K012", "fact_id": "F006"}, {"sourceId": "K012", "factId": "F007", "content": "f-string 在字符串前加 f，用 {} 嵌入变量或表达式。", "source_id": "K012", "fact_id": "F007"}, {"sourceId": "K012", "factId": "F008", "content": "s.strip() 返回去除首尾空白的新字符串，s.lower()/s.upper() 返回转换大小写后的新字符串。", "source_id": "K012", "fact_id": "F008"}, {"sourceId": "K012", "factId": "F009", "content": "s.replace(old, new) 返回替换子串后的新字符串，s.find(sub) 返回子串首次出现的位置。", "source_id": "K012", "fact_id": "F009"}, {"sourceId": "K012", "factId": "F010", "content": "s.startswith(prefix) 与 s.endswith(suffix) 分别返回字符串是否以指定内容开头或结尾的布尔值。", "source_id": "K012", "fact_id": "F010"}, {"sourceId": "K012", "factId": "F011", "content": "字符串比较按字符的 Unicode 码点逐字符进行。", "source_id": "K012", "fact_id": "F011"}, {"sourceId": "K012", "factId": "F012", "content": "三引号字符串可跨行书写，常用于多行文本与文档字符串。", "source_id": "K012", "fact_id": "F012"}],
      examples: [{"title": "拆分和处理成绩数据", "code": "data = \"小明:92,小红:85,小刚:78\"\npairs = data.split(\",\")\nfor pair in pairs:\n    name, score = pair.split(\":\")\n    print(name, \"的成绩是\", score)", "explanation": "split 把逗号分隔的字符串拆成列表，再逐个拆分出姓名和成绩。"}, {"title": "拼接报告", "code": "names = [\"小明\", \"小红\", \"小刚\"]\nscores = [92, 85, 78]\nlines = []\nfor i in range(len(names)):\n    lines.append(names[i] + \"：\" + str(scores[i]) + \"分\")\nreport = \"\\n\".join(lines)\nprint(report)", "explanation": "join 把每行报告用换行符连接成完整的段落文本。"}],
