      examples: [{"title": "用 math 模块计算统计值", "code": "import math\n\nscores = [85, 92, 78, 95, 88]\nmean = sum(scores) / len(scores)\nstd_dev = math.sqrt(sum((x - mean) ** 2 for x in scores) / len(scores))\nprint(\"平均分：\", round(mean, 2))\nprint(\"标准差：\", round(std_dev, 2))", "explanation": "import math 导入整个 math 模块，math.sqrt 使用其中的平方根函数。"}, {"title": "从模块导入指定函数", "code": "from math import sqrt, pi\n\nr = 5\narea = pi * r ** 2\nprint(\"半径为\", r, \"的圆面积：\", round(area, 2))\n\nresult = sqrt(144)\nprint(\"144 的平方根：\", result)", "explanation": "from ... import ... 只导入需要的函数或常量，调用时无需加模块前缀。"}],
